/** Get a manifest entry by ID */
export function getManifestEntry(id: string): ManifestRegistryEntry | undefined {
  return MANIFEST_REGISTRY.find((m) => m.id === id);
}


/** Get all manifests by class */
export function getManifestsByClass(cls: ManifestRegistryEntry["class"]): ManifestRegistryEntry[] {
  return MANIFEST_REGISTRY.filter((m) => m.class === cls);
}

/** Get all manifests by owner */
export function getManifestsByOwner(owner: ManifestRegistryEntry["owner"]): ManifestRegistryEntry[] {
  return MANIFEST_REGISTRY.filter((m) => m.owner === owner);
}

/** Get all authoritative manifests */
export function getAuthoritativeManifests(): ManifestRegistryEntry[] {
  return MANIFEST_REGISTRY.filter((m) => m.authority === "authoritative");
}

/** Total manifest count */
export const MANIFEST_COUNT = MANIFEST_REGISTRY.length;
